import sys

def main():
    data = sys.stdin.read().split()
    if not data:
        return
    try:
        r = int(data[0])
    except ValueError:
        return

    for length in range(r, 0, -1):
        print(''.join(chr(ord('A') + i) for i in range(length)))

if __name__ == "__main__":
    main()
